/* @lc app=leetcode id=3418 lang=kotlin */ class Solution { fun maximumAmount(coins: Array<IntArray>): Int = coins[0].size.let { n -> coins.indices.fold(Array(n) { IntArray(3) { -1_000_000_000 } }) { prev, i -> Array(n) { IntArray(3) }.also { cur -> (0 until n).forEach { j -> (0..2).forEach { t -> cur[j][t] = coins[i][j].let { c -> (if (i == 0 && j == 0) (if (t == 0) 0 else -1_000_000_000) else maxOf(if (i > 0) prev[j][t] else -1_000_000_000, if (j > 0) cur[j - 1][t] else -1_000_000_000)).let { bt -> maxOf(bt + c, if (t > 0 && c < 0) (if (i == 0 && j == 0) (if (t - 1 == 0) 0 else -1_000_000_000) else maxOf(if (i > 0) prev[j][t - 1] else -1_000_000_000, if (j > 0) cur[j - 1][t - 1] else -1_000_000_000)) else -1_000_000_000) } } } } } }.last().max() } }